func minWindow(s string, t string) string {
	if t == "" {
		return ""
	}

	countT := make(map[rune]int)
	window := make(map[rune]int)

	for _, c := range t {
		countT[c]++
	}

	have, need := 0, len(countT)
	res := []int{-1, -1}
	resLen := math.Inf(1)
	l := 0

	for r, c := range s {
		window[c]++

		if val, ok := countT[c]; ok && window[c] == val {
			have++
		}

		for have == need {
			if float64(r-l+1) < resLen {
				res[0], res[1] = l, r
				resLen = float64(r - l + 1)
			}

			leftChar := rune(s[l])
			window[leftChar]--
			if val, ok := countT[leftChar]; ok && window[leftChar] < val {
				have--
			}
			l++
		}
	}

	if resLen == math.Inf(1) {
		return ""
	}
	return s[res[0] : res[1]+1]
}

func isValid(str string) bool {
	Map := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}

	for _, c := range str {
		if _, ok := Map[c]; !ok {
			stack = append(stack, c)
			continue
		}
		if len(stack) == 0 || stack[len(stack)-1] != Map[c] {
			return false
		}
		stack = stack[:len(stack)-1]
	}

	return len(stack) == 0
}

func findMin(nums []int) int {
	start, end := 0, len(nums)-1
	currMin := math.MaxInt32

	for start < end {
		mid := start + (end-start)/2
		currMin = min(currMin, nums[mid])

		if nums[mid] > nums[end] {
			start = mid + 1

		} else {
			end = mid - 1

		}
	}

	return min(currMin, nums[start])
}

func search(nums []int, target int) int {
	l, r := 0, len(nums)-1

	for l <= r {
		mid := (l + r) / 2
		if target == nums[mid] {
			return mid
		}

		if nums[l] <= nums[mid] {
			if target > nums[mid] || target < nums[l] {
				l = mid + 1
			} else {
				r = mid - 1
			}

		} else {
			if target < nums[mid] || target > nums[r] {
				r = mid - 1
			} else {
				l = mid + 1
			}
		}
	}

	return -1
}

