func combinationSum(nums []int, target int) [][]int {
	var res [][]int

	var dfs func(i int, cur []int, total int)
	dfs = func(i int, cur []int, total int) {
		if total == target {
			tmp := make([]int, len(cur))
			copy(tmp, cur)
			res = append(res, tmp)
			return
		}
		if i >= len(nums) || total > target {
			return
		}

		cur = append(cur, nums[i])
		dfs(i, cur, total+nums[i])
		cur = cur[:len(cur)-1]
		dfs(i+1, cur, total)
	}

	dfs(0, []int{}, 0)
	return res
}

func exist(board [][]byte, word string) bool {
	m := len(board)
	n := len(board[0])

	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			if board[i][j] == word[0] {
				if dfs(board, word, 0, i, j, m, n) {
					return true
				}
			}
		}
	}

	return false
}

func dfs(board [][]byte, word string, index, i, j, m, n int) bool {
	if i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[index] {
		return false
	}
	if index == len(word)-1 {
		return true
	}

	temp := board[i][j]
	board[i][j] = '#'

	if dfs(board, word, index+1, i-1, j, m, n) ||
		dfs(board, word, index+1, i+1, j, m, n) ||
		dfs(board, word, index+1, i, j-1, m, n) ||
		dfs(board, word, index+1, i, j+1, m, n) {
		return true
	}

	board[i][j] = temp
	return false
}

