func cloneGraph(node *Node) *Node {
	oldToNew := make(map[*Node]*Node)

	var dfs func(node *Node) *Node
	dfs = func(node *Node) *Node {
		if _, ok := oldToNew[node]; ok {
			return oldToNew[node]
		}
		copy := &Node{Val: node.Val}
		oldToNew[node] = copy
		for _, nei := range node.Neighbors {
			copy.Neighbors = append(copy.Neighbors, dfs(nei))
		}
		return copy
	}

	if node != nil {
		return dfs(node)
	}
	return nil
}

func pacificAtlantic(heights [][]int) [][]int {
	rows, cols := len(heights), len(heights[0])
	pac, atl := make(map[[2]int]bool), make(map[[2]int]bool)

	var dfs func(r, c int, visit map[[2]int]bool, prevHeight int)
	dfs = func(r, c int, visit map[[2]int]bool, prevHeight int) {
		if visit[[2]int{r, c}] ||
			r < 0 ||
			c < 0 ||
			r == rows ||
			c == cols ||
			heights[r][c] < prevHeight {
			return
		}
		visit[[2]int{r, c}] = true
		dfs(r+1, c, visit, heights[r][c])
		dfs(r-1, c, visit, heights[r][c])
		dfs(r, c+1, visit, heights[r][c])
		dfs(r, c-1, visit, heights[r][c])
	}

	for c := 0; c < cols; c++ {
		dfs(0, c, pac, heights[0][c])
		dfs(rows-1, c, atl, heights[rows-1][c])
	}

	for r := 0; r < rows; r++ {
		dfs(r, 0, pac, heights[r][0])
		dfs(r, cols-1, atl, heights[r][cols-1])
	}

	res := [][]int{}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if pac[[2]int{r, c}] && atl[[2]int{r, c}] {
				res = append(res, []int{r, c})
			}
		}
	}
	return res
}

func canFinish(numCourses int, prerequisites [][]int) bool {
	preMap := make(map[int][]int)
	for i := 0; i < numCourses; i++ {
		preMap[i] = []int{}
	}
	for _, prereq := range prerequisites {
		crs, pre := prereq[0], prereq[1]
		preMap[crs] = append(preMap[crs], pre)
	}

	visiting := make(map[int]bool)

	var dfs func(crs int) bool
	dfs = func(crs int) bool {
		if visiting[crs] {
			return false
		}
		if len(preMap[crs]) == 0 {
			return true
		}

		visiting[crs] = true
		for _, pre := range preMap[crs] {
			if !dfs(pre) {
				return false
			}
		}
		delete(visiting, crs)
		preMap[crs] = []int{}
		return true
	}

	for c := 0; c < numCourses; c++ {
		if !dfs(c) {
			return false
		}
	}
	return true
}

func validTree(n int, edges [][]int) bool {
	if n == 0 {
		return true
	}
	adj := make(map[int][]int)
	for i := 0; i < n; i++ {
		adj[i] = []int{}
	}
	for _, edge := range edges {
		n1, n2 := edge[0], edge[1]
		adj[n1] = append(adj[n1], n2)
		adj[n2] = append(adj[n2], n1)
	}

	visit := make(map[int]bool)

	var dfs func(i, prev int) bool
	dfs = func(i, prev int) bool {
		if visit[i] {
			return false
		}

		visit[i] = true
		for _, j := range adj[i] {
			if j == prev {
				continue
			}
			if !dfs(j, i) {
				return false
			}
		}
		return true
	}

	return dfs(0, -1) && n == len(visit)
}

